<script setup>
import { computed,ref,watch,onMounted,onBeforeUnmount } from 'vue'
import { useDisplay } from 'vuetify'
import { useRoute,useRouter } from 'vue-router'
import { request,post,queryString,isActiveJob,paperKey,safeUrl,acceptsJobSnapshot } from './api.js'
const route=useRoute(),router=useRouter()
const {width:viewportWidth}=useDisplay()
const drawerWidth=computed(()=>viewportWidth.value<960?viewportWidth.value:Math.min(880,Math.max(400,viewportWidth.value/2)))
const lang=ref(localStorage.getItem('le.language')||'zh'),reduced=ref(localStorage.getItem('le.reduced')==='true')
const t=(zh,en)=>lang.value==='zh'?zh:en
watch(lang,value=>{localStorage.setItem('le.language',value);document.documentElement.lang=value==='zh'?'zh-CN':'en'})
watch(reduced,value=>{localStorage.setItem('le.reduced',String(value));document.body.classList.toggle('reduced',value)})
const page=computed(()=>route.name==='paper'?'paper':String(route.name||'home').replace('project-',''))
const projectId=computed(()=>String(route.params.projectId||'')),project=ref(null),projects=ref([]),job=ref(null)
const busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),navOpen=ref(false),projectError=ref(false)
const papers=ref([]),total=ref(0),facets=ref({}),detail=ref(null),landscape=ref(null),questions=ref(null),review=ref(null),settings=ref(null),health=ref(null),plan=ref(null),exportFile=ref(null)
const filters=ref({q:'',provider:'',ccf_rank:'',year_from:'',year_to:'',min_score:0,sort:'relevance',page:1,page_size:10})
const selected=ref([]),query=ref(''),direction=ref(''),name=ref(''),yearFrom=ref(2020),yearTo=ref(new Date().getFullYear()),maxPapers=ref(100),providers=ref(['semantic_scholar','openalex','arxiv','crossref','openreview']),mode=ref('systematic')
const englishQuery=ref(''),rankingMode=ref('semantic')
const rounds=ref(2),expansionMax=ref(100),budget=ref(120),resume=ref(false)
const reviewStage=ref('title_abstract'),decisionReason=ref(''),readConfirmed=ref(false),calibrationLabel=ref('relevant'),calibrationLabels=ref([])
const exportFormat=ref('evidence_pack'),exportScope=ref('corpus'),saveName=ref(''),uploadInput=ref(null)
const keyInputs=ref({s2_api_key:'',openalex_api_key:'',serpapi_api_key:'',unpaywall_email:''}),credentialsMessage=ref('')
const graphMode=ref('citation'),pathStart=ref(''),pathEnd=ref(''),pathResult=ref(null),questionSelection=ref(null)
let timer=null,loadGeneration=0
const activeJob=computed(()=>isActiveJob(job.value))
const currentProjectPath=computed(()=>projectId.value?`/projects/${projectId.value}`:'')
const navigation=computed(()=>[
  ['search',t('检索','Search')],['results',t('文献结果','Results')],['expand',t('引文扩展','Expand')],['landscape',t('证据版图','Landscape')],['questions',t('候选问题','Questions')],['review',t('人工筛选','Review')],['export',t('导出与保存','Export')]
])
const title=computed(()=>({home:'LEExtractor',search:t('从研究问题开始','Start with a research question'),results:t('文献结果','Literature results'),paper:t('论文详情','Paper details'),expand:t('沿着证据继续探索','Follow the evidence'),landscape:t('研究证据版图','Research landscape'),questions:t('候选研究问题','Candidate questions'),review:t('人工筛选与标定','Screening and calibration'),export:t('导出与保存','Export and save'),projects:t('研究项目','Research projects'),settings:t('设置与诊断','Settings and diagnostics')})[page.value])
const lead=computed(()=>({search:t('描述方向，核对检索计划，再向真实来源发起检索。','Describe your focus, check the plan, then query the sources.'),results:t('比较文献、查看发现依据，并挑选下一轮扩展的种子。','Compare records, inspect discovery evidence and select expansion seeds.'),expand:t('向前追踪引用，向后追溯参考文献；每一轮保留发现轨迹。','Explore citations and references; retain evidence for every discovery.'),landscape:t('当前项目内的关系与分布，反映的是已获取的语料。','Relationships and distributions within the corpus acquired for this project.'),questions:t('从已有语料中整理的探索线索，需要阅读证据后人工判断。','Exploration leads derived from the corpus; assess them against the evidence.'),review:t('相关度用于排序，人工决定用于筛选；未获取全文不会自动排除。','Relevance supports ranking. Screening requires human decisions. Missing full text is not automatic exclusion.'),export:t('导出文献、发现轨迹和会话，便于复核与团队接手。','Export records, discovery evidence and the session for review and handoff.'),projects:t('恢复已保存的工作，或创建一个独立的研究项目。','Resume saved work or create an independent research project.'),settings:t('来源凭据保存在本机服务端，页面只显示配置状态。','Provider credentials stay on the local server; the browser displays configuration status only.')})[page.value]||'')
const sourceOptions=computed(()=>[{title:t('所有来源','All sources'),value:''},...(facets.value.providers||[]).map(row=>({title:sourceLabel(row.value),value:row.value}))])
const pages=computed(()=>Math.max(1,Math.ceil(total.value/filters.value.page_size)))
const paperOptions=computed(()=>papers.value.map(p=>({title:p.title,value:paperKey(p)})))
const questionItems=computed(()=>questions.value?.items||questions.value?.questions||[])
const relationEdges=computed(()=>{const g=landscape.value?.graph||landscape.value||{};const edges=g.edges||g.links||[];return edges.filter(edge=>graphMode.value==='all'||(edge.edge_type||edge.relation_type||edge.type||edge.kind||'citation')===graphMode.value)})
const graphNodes=computed(()=>landscape.value?.graph?.nodes||landscape.value?.nodes||[])
const graphPositions=computed(()=>{const list=graphNodes.value.slice(0,48),map=new Map();list.forEach((node,i)=>{const angle=i*2*Math.PI/Math.max(1,list.length);map.set(node.paper_key||node.id,{...node,x:400+310*Math.cos(angle),y:230+180*Math.sin(angle)})});return map})
const visibleGraphEdges=computed(()=>relationEdges.value.slice(0,160).map(edge=>({edge,a:graphPositions.value.get(edge.source_key||edge.source),b:graphPositions.value.get(edge.target_key||edge.target)})).filter(item=>item.a&&item.b))
const topicRows=computed(()=>landscape.value?.landscape?.topics?.topics||[])
const temporal=computed(()=>landscape.value?.landscape?.temporal||{})
const timelineRows=computed(()=>Object.entries(temporal.value.timeline||{}))
const timelineMax=computed(()=>Math.max(1,...timelineRows.value.map(([,count])=>count)))
const coverage=computed(()=>landscape.value?.landscape?.coverage||{})
const novelty=computed(()=>landscape.value?.landscape?.novelty||{})
const referenceFacts=computed(()=>questions.value?.citation_coverage||{})
const knownProviders=['semantic_scholar','openalex','arxiv','crossref','openreview','google_scholar']
const normalizeProvider=source=>source==='s2'?'semantic_scholar':source
const plannedQueries=computed(()=>Object.fromEntries(Object.entries(plan.value?.provider_queries||plan.value?.queries||{}).filter(([source])=>providers.value.includes(normalizeProvider(source)))))
const manifestProviders=computed(()=>project.value?.search_manifest?.selected_providers||project.value?.search_manifest?.provider_results?.map(row=>row.provider)||Object.keys(project.value?.search_manifest?.provider_counts||{}))
const providerResults=computed(()=>(project.value?.search_manifest?.provider_results||[]).filter(row=>manifestProviders.value.map(normalizeProvider).includes(normalizeProvider(row.provider))))
const providerDiagnostics=computed(()=>(project.value?.search_manifest?.diagnostics||[]).filter(row=>manifestProviders.value.map(normalizeProvider).includes(normalizeProvider(row.source))))
const hasRateLimit=computed(()=>providerResults.value.some(row=>row.status==='rate_limited'||row.request_stats?.rate_limited>0))
const hasRetrievalFailure=computed(()=>providerResults.value.some(row=>row.failed===true||['rate_limited','timeout','provider_error','partial','budget_exhausted'].includes(row.status)))
function sourceLabel(source){return {s2:'Semantic Scholar',semantic_scholar:'Semantic Scholar',openalex:'OpenAlex',arxiv:'arXiv',crossref:'Crossref',openreview:'OpenReview',google_scholar:'Google Scholar',demo_fixture:t('模拟数据','Synthetic data')}[source]||source}
function display(value){return value===null||value===undefined||value===''?'—':String(value)}
function authors(paper){return (paper?.authors||[]).map(a=>typeof a==='string'?a:a.name).join(', ')}
function percent(value){return Number.isFinite(Number(value))?Number(value).toFixed(3):'—'}
function label(key){return ({queued:t('排队中','Queued'),running:t('进行中','Running'),completed:t('已完成','Completed'),partial:t('部分完成','Partial'),failed:t('失败','Failed'),canceled:t('已取消','Canceled'),interrupted:t('已中断','Interrupted'),saturated:t('满足饱和条件','Saturation rule met'),no_new_results:t('没有新增文献','No new records'),low_yield:t('新增数量较少','Low yield'),max_rounds:t('达到轮次上限','Round limit reached'),truncated:t('达到文献上限','Record limit reached'),budget_exhausted:t('预算已用尽','Budget exhausted'),api_failure:t('来源调用失败','Provider failure'),local_model_failure:t('本地模型加载失败','Local model unavailable'),local_embedding:t('正在加载本地语义模型','Loading local embedding model'),submission:t('投稿，录用未核实','Submission; acceptance unverified'),accepted:t('已录用，论文类型待核实','Accepted; paper type unverified'),rejected_or_withdrawn:t('拒稿或撤稿','Rejected or withdrawn'),published_metadata:t('已有出版元数据','Published metadata'),unknown:t('尚未核实','Unverified'),accept:t('纳入','Include'),reject:t('排除','Exclude'),maybe:t('待定','Maybe'),undecided:t('待筛选','Undecided'),pending:t('待筛选','Pending'),not_started:t('未开始','Not started'),hypothesis:t('待验证假设','Hypothesis'),no_open_access:t('无可获取开放全文','No available open full text'),download_failed:t('获取失败','Retrieval failed'),success:t('正常完成','Success'),success_empty:t('正常完成且零结果','Successful empty result'),rate_limited:t('来源限流','Rate limited'),timeout:t('来源超时','Provider timeout'),provider_error:t('来源错误','Provider error'),not_attempted:t('未尝试','Not attempted'),downloaded:t('已获取','Retrieved')})[key]||display(key)}
function messageFrom(err){const detail=err.detail;if(typeof detail==='string')return `${err.message} · ${detail}`;return err.message||String(err)}
async function action(task){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{return await task()}catch(err){error.value=messageFrom(err)}finally{busy.value=false}}
async function projectRequest(suffix,options){if(!projectId.value)throw new Error(t('请先选择或创建项目','Select or create a project first'));return request(`/projects/${encodeURIComponent(projectId.value)}${suffix}`,options)}
async function projectPost(suffix,body={}){const revisionWrites=['/search','/expand','/similar','/screening-decisions','/calibration','/downloads','/save'];return projectRequest(suffix,{method:'POST',body:revisionWrites.includes(suffix)?{expected_revision:project.value?.revision,...body}:body})}
function navigate(name){navOpen.value=false;router.push(projectId.value?`${currentProjectPath.value}/${name}`:'/search')}
async function loadProject(){const data=await projectRequest('');project.value=data;projectError.value=false;saveName.value=data.name||'';return data}
async function loadPapers(){const data=await projectRequest(`/papers?${queryString(filters.value)}`);papers.value=data.items||[];total.value=data.total||0;return data}
async function loadPage(){const generation=++loadGeneration;loading.value=true;error.value='';projectError.value=false;detail.value=null;try{
  if(projectId.value){const data=await loadProject();if(generation!==loadGeneration)return;if(data.active_job_id)await followJob(data.active_job_id);else if(job.value?.project_id!==projectId.value){job.value=null;const previous=sessionStorage.getItem(`le.job.${projectId.value}`);if(previous){try{await followJob(previous)}catch{sessionStorage.removeItem(`le.job.${projectId.value}`)}}}
    if(['results','expand','review','export'].includes(page.value))await loadPapers();
    if(page.value==='results')facets.value=await projectRequest('/facets');
    if(page.value==='search'){query.value=String(route.query.q||data.topic||'');direction.value=String(route.query.direction||data.research_direction||'');name.value=data.name||'';const savedProviders=data.search_manifest?.selected_providers;if(Array.isArray(savedProviders)&&savedProviders.length)providers.value=savedProviders.map(normalizeProvider).filter(source=>knownProviders.includes(source))}
    if(page.value==='paper')detail.value=await projectRequest(`/papers/${encodeURIComponent(String(route.params.paperKey))}`);
    if(page.value==='landscape')landscape.value=await projectRequest('/landscape');
    if(page.value==='questions')questions.value=await projectRequest('/questions');
    if(page.value==='review')await loadReview();
  }else{project.value=null;job.value=null;if(page.value==='projects'||page.value==='home')projects.value=(await request('/projects')).items||[];
    if(page.value==='settings'){settings.value=await request('/settings');health.value=await request('/health')}
  }
 }catch(err){if(generation===loadGeneration){error.value=messageFrom(err);if(err.status===404&&projectId.value)projectError.value=true}}finally{if(generation===loadGeneration)loading.value=false}}
function jobId(data){return data.job_id||data.jobId||data.id}
async function followJob(id){if(!id)return;clearTimeout(timer);job.value=await request(`/jobs/${encodeURIComponent(id)}`);if(job.value.project_id===projectId.value)sessionStorage.setItem(`le.job.${projectId.value}`,id);schedulePoll()}
function schedulePoll(){clearTimeout(timer);if(activeJob.value)timer=setTimeout(pollJob,1200)}
async function pollJob(){if(!job.value)return;const id=jobId(job.value),boundProject=projectId.value;try{const updated=await request(`/jobs/${encodeURIComponent(id)}`);if(boundProject!==projectId.value||id!==jobId(job.value)||!acceptsJobSnapshot(job.value,updated,projectId.value))return;job.value=updated;if(isActiveJob(updated)){schedulePoll();return}await loadProject();if(['results','expand','review','export'].includes(page.value))await loadPapers();if(page.value==='review')await loadReview();notice.value=`${t('任务','Job')}: ${label(updated.status)}${updated.stop_reason?' · '+label(updated.stop_reason):''}`;if(updated.error)error.value=typeof updated.error==='string'?updated.error:updated.error.message}catch(err){error.value=messageFrom(err);clearTimeout(timer)}}
async function startJob(suffix,body){const result=await projectPost(suffix,body);await followJob(jobId(result));await loadProject();return result}
async function cancelJob(){await action(async()=>{job.value=await post(`/jobs/${encodeURIComponent(jobId(job.value))}/cancel`);schedulePoll();notice.value=t('已请求取消；任务将在安全检查点停止。','Cancellation requested. The job stops at the next safe checkpoint.')})}
async function ensureProject(){if(projectId.value)return projectId.value;const data=await post('/projects',{name:name.value.trim()||query.value.trim(),topic:query.value.trim(),research_direction:direction.value.trim()});const id=data.project_id;await router.push(`/projects/${encodeURIComponent(id)}/search`);await loadProject();return id}
function searchPayload(){return {query:query.value.trim(),research_direction:direction.value.trim(),year_from:Number(yearFrom.value),year_to:Number(yearTo.value),max_papers:Number(maxPapers.value),providers:[...providers.value],mode:mode.value,translate:true,search_keywords:englishQuery.value.trim(),ranking_mode:rankingMode.value,http_budget:Number(budget.value)}}
async function previewPlan(){await action(async()=>{if(!query.value.trim())throw new Error(t('请输入检索主题','Enter a search topic'));if(!providers.value.length)throw new Error(t('至少选择一个检索来源','Select at least one search provider'));await ensureProject();plan.value=await projectPost('/query-plan',{topic:query.value.trim(),research_direction:direction.value.trim(),translate:true,search_keywords:englishQuery.value.trim(),year_from:Number(yearFrom.value),year_to:Number(yearTo.value)});englishQuery.value=plan.value.translation?.translated||englishQuery.value})}
async function search(){await action(async()=>{if(!query.value.trim())throw new Error(t('请输入检索主题','Enter a search topic'));if(!providers.value.length)throw new Error(t('至少选择一个检索来源','Select at least one search provider'));if(Number(yearFrom.value)>Number(yearTo.value))throw new Error(t('起始年份不能大于结束年份','The starting year must precede the ending year'));await ensureProject();await startJob('/search',searchPayload());await router.push(`${currentProjectPath.value}/results`)})}
async function loadDemo(){await action(async()=>{const data=await post('/demo/projects');selected.value=[];filters.value.page=1;await router.push(`/projects/${encodeURIComponent(data.project_id)}/results`)})}
async function createProject(){await action(async()=>{if(!name.value.trim())throw new Error(t('请输入项目名称','Enter a project name'));const data=await post('/projects',{name:name.value.trim(),topic:query.value.trim(),research_direction:direction.value.trim()});await router.push(`/projects/${encodeURIComponent(data.project_id)}/search`)})}
async function filterChanged(){filters.value.page=1;await action(loadPapers)}
function toggleSeed(paper){const key=paperKey(paper);selected.value=selected.value.includes(key)?selected.value.filter(x=>x!==key):[...selected.value,key];saveSeeds()}
function saveSeeds(){if(projectId.value)sessionStorage.setItem(`le.seeds.${projectId.value}`,JSON.stringify(selected.value))}
function selectPage(){const keys=papers.value.map(paperKey);selected.value=[...new Set([...selected.value,...keys])];saveSeeds()}
function openPaper(paper){router.push(`${currentProjectPath.value}/papers/${encodeURIComponent(paperKey(paper))}`)}
function backToResults(){router.push(`${currentProjectPath.value}/results`)}
async function expand(){await action(async()=>{if(!selected.value.length&&!resume.value)throw new Error(t('请先在结果页选择种子文献','Select seed papers in Results first'));await startJob('/expand',{seed_keys:selected.value,num_seeds:selected.value.length||5,max_rounds:Number(rounds.value),max_per_direction:Number(expansionMax.value),year_from:Number(yearFrom.value),year_to:Number(yearTo.value),http_budget:Number(budget.value),resume:resume.value})})}
async function similar(){await action(async()=>{if(!selected.value.length)throw new Error(t('请先选择种子文献','Select seed papers first'));await startJob('/similar',{seed_keys:selected.value,num_seeds:selected.value.length,top_k:Number(expansionMax.value),http_budget:Number(budget.value)})})}
async function decide(paper,decision){await action(async()=>{if(reviewStage.value==='full_text'&&decision==='accept'&&!readConfirmed.value)throw new Error(t('纳入全文前，请确认你已阅读全文','Confirm that you have read the full text before inclusion'));await projectPost('/screening-decisions',{paper_key:paperKey(paper),stage:reviewStage.value,decision,reason:decisionReason.value,read_confirmed:readConfirmed.value});await loadProject();await loadReview();await loadPapers();decisionReason.value='';readConfirmed.value=false;notice.value=t('人工决定已保存','Screening decision saved')})}
async function downloads(keys){await action(async()=>{const paper_keys=keys||selected.value;if(!paper_keys.length)throw new Error(t('请先选择文献','Select papers first'));await startJob('/downloads',{paper_keys})})}
function addLabel(paper){const key=paperKey(paper);calibrationLabels.value=calibrationLabels.value.filter(row=>row.paper_key!==key);calibrationLabels.value.push({paper_key:key,label:calibrationLabel.value});notice.value=t('标签已加入本次标定，提交后生效','Label added to this calibration. Submit to apply.')}
async function calibrate(){await action(async()=>{if(!calibrationLabels.value.length)throw new Error(t('请先添加人工标签','Add human labels first'));await projectPost('/calibration',{labels:calibrationLabels.value});await loadProject();await loadReview();notice.value=t('标定已保存，适用性由后端判定。','Calibration saved. Applicability is assessed by the backend.');calibrationLabels.value=[]})}
async function exportProject(){await action(async()=>{if(exportScope.value==='selected'&&!selected.value.length)throw new Error(t('请先选择文献','Select papers first'));exportFile.value=await projectPost('/exports',{format:exportFormat.value,scope:exportScope.value,paper_keys:selected.value});notice.value=t('导出文件已生成，请点击下载。','Export generated. Use the download link.')})}
async function save(){await action(async()=>{await projectPost('/save',{name:saveName.value||project.value.name,expected_revision:project.value.revision});await loadProject();notice.value=t('项目已保存','Project saved')})}
async function importSession(event){const file=event.target.files?.[0];if(!file)return;await action(async()=>{if(file.size>20*1024*1024)throw new Error(t('会话文件不能超过 20 MB','Session files must be at most 20 MB'));let session;try{session=JSON.parse(await file.text())}catch{throw new Error(t('请选择有效的 JSON 会话文件','Select a valid JSON session file'))}const data=await post('/projects/import',{session});selected.value=[];await router.push(`/projects/${encodeURIComponent(data.project_id)}/results`);notice.value=t('已导入为独立项目','Imported as an independent project')});event.target.value=''}
async function saveCredentials(){await action(async()=>{const payload=Object.fromEntries(Object.entries(keyInputs.value).filter(([,v])=>v.trim()).map(([k,v])=>[k,v.trim()]));if(!Object.keys(payload).length)throw new Error(t('请输入需要更新的凭据','Enter a credential to update'));keyInputs.value={s2_api_key:'',openalex_api_key:'',serpapi_api_key:'',unpaywall_email:''};settings.value=await post('/settings',payload);credentialsMessage.value=t('配置已更新','Configuration updated')})}
async function findPath(){await action(async()=>{if(!pathStart.value||!pathEnd.value)throw new Error(t('请选择路径起点和终点','Select start and end papers'));pathResult.value=await projectRequest(`/landscape/path?${queryString({source:pathStart.value,target:pathEnd.value})}`)})}
function restoreSeeds(){try{selected.value=JSON.parse(sessionStorage.getItem(`le.seeds.${projectId.value}`)||'[]')}catch{selected.value=[]}}
async function loadReview(){review.value=await projectRequest(`/review?stage=${reviewStage.value}`)}
const progressEntries=computed(()=>Object.entries(job.value?.progress||{}).filter(([,v])=>typeof v!=='object'))
watch(()=>route.fullPath,async()=>{clearTimeout(timer);navOpen.value=false;questionSelection.value=null;plan.value=null;exportFile.value=null;restoreSeeds();await loadPage()})
watch([query,direction],()=>{englishQuery.value='';plan.value=null})
watch(reviewStage,()=>{readConfirmed.value=false;if(page.value==='review')action(loadReview)})
onMounted(async()=>{document.documentElement.lang=lang.value==='zh'?'zh-CN':'en';document.body.classList.toggle('reduced',reduced.value);restoreSeeds();await loadPage();try{settings.value=await request('/settings');if(settings.value.providers?.google_scholar?.configured&&!providers.value.includes('google_scholar'))providers.value.push('google_scholar')}catch{}})
onBeforeUnmount(()=>clearTimeout(timer))
</script>

<template>
<v-app :class="{'theme-home':page==='home'}">
  <a class="skip-link" href="#main">{{t('跳到主要内容','Skip to content')}}</a>
  <header class="topbar">
    <router-link to="/" class="brand" aria-label="LEExtractor home">LEExtractor<span class="brand-tag">{{t('文献研究工作台','Research workspace')}}</span></router-link>
    <nav class="toplinks" :aria-label="t('主导航','Main navigation')"><router-link to="/projects">{{t('项目','Projects')}}</router-link><router-link to="/settings">{{t('设置','Settings')}}</router-link><v-btn size="small" variant="text" @click="lang=lang==='zh'?'en':'zh'" :aria-label="t('切换到英文','Switch to Chinese')">{{lang==='zh'?'EN':'中文'}}</v-btn><v-btn size="small" variant="outlined" @click="navOpen=!navOpen" :aria-expanded="navOpen">{{t('导航','Navigate')}} <span aria-hidden="true">☰</span></v-btn></nav>
  </header>
  <nav v-if="navOpen" class="nav-panel" :aria-label="t('工作台导航','Workspace navigation')"><router-link to="/">{{t('首页','Home')}}</router-link><button v-for="[key,text] in navigation" :key="key" @click="navigate(key)">{{text}}</button><router-link to="/projects">{{t('全部项目','All projects')}}</router-link></nav>
  <nav v-if="projectId&&!projectError" class="work-tabs" :aria-label="t('项目页面','Project pages')"><button v-for="[key,text] in navigation" :key="key" :class="{active:page===key||(key==='results'&&page==='paper')}" @click="navigate(key)">{{text}}</button><span class="project-name">{{project?.name||projectId}}</span></nav>
  <main id="main">
    <div v-if="error" class="global-message"><v-alert type="error" variant="tonal" closable @click:close="error=''" role="alert">{{error}}</v-alert></div>
    <div v-if="notice" class="global-message"><v-alert type="info" variant="tonal" closable @click:close="notice=''" role="status">{{notice}}</v-alert></div>
    <div v-if="project?.demo" class="demo-banner">{{t('隔离演示项目 · 所有文献与关系为模拟数据，不可作为真实研究证据。','Isolated demo project · All records and relationships are synthetic, not research evidence.')}}</div>
    <div v-if="loading" class="loading-line" role="status"><v-progress-linear indeterminate color="primary" :height="2"/><span>{{t('正在读取项目…','Loading project…')}}</span></div>
    <section v-if="projectError" class="container empty"><h1>{{t('项目未找到','Project not found')}}</h1><p>{{t('这个项目可能已移除，请在项目列表中重新选择。','This project may have been removed. Select a project from the list.')}}</p><v-btn to="/projects" color="primary">{{t('查看项目','View projects')}}</v-btn></section>

    <template v-else-if="page==='home'">
      <section class="cover"><button class="hero-button" @click="router.push('/search')" :aria-label="t('开始探索','Start exploring')"><span class="wordmark"><span>LEE</span><span class="x-slot"><span class="rotor"/></span><span>tractor</span></span><span class="invitation">{{t('惟学无际，际于天地 · 点击开始探索','Knowledge without limits · Begin exploring')}}</span></button><img class="eagle" src="/assets/qiushi-characters.png" :alt="t('求是鹰字符画','Qiushi eagle character art')"/></section>
      <section class="home-band"><div class="logo-band"><span>{{t('参赛单位','Affiliation')}}</span><img src="/assets/zju-wordmark.png" :alt="t('浙江大学','Zhejiang University')"/><span class="home-tag">{{t('可追溯的文献探索','Traceable literature exploration')}}</span></div></section>
      <section class="home-band"><p class="eyebrow">LITERATURE · EVIDENCE · EXPLORATION</p><h2>{{t('让每一次探索，留下依据。','Keep the evidence behind every discovery.')}}</h2><p class="home-copy">{{t('从多来源检索走向引文扩展，在证据版图中比较方向，由你完成筛选与判断。记录与发现轨迹一起保存，研究过程可以复核。','Search across sources, expand citation networks and compare directions in an evidence landscape. Make your own screening decisions. Records and discovery trails remain available for review.')}}</p><div class="actions"><v-btn size="large" color="primary" to="/search">{{t('开始检索','Start a search')}}</v-btn><v-btn size="large" variant="outlined" @click="loadDemo" :loading="busy">{{t('创建离线演示项目','Create offline demo')}}</v-btn><v-btn size="large" variant="text" to="/projects">{{t('恢复已有项目','Resume a project')}}</v-btn></div></section>
      <section class="home-band"><div class="cols-3"><article class="feature"><span>01 / DISCOVERY</span><h3>{{t('查找与扩展','Search and expand')}}</h3><p>{{t('检索来源独立计数，强标识去重，使用真实引文和参考文献继续探索。','Provider counts remain separate. Strong identifiers deduplicate records. Expand with observed citations and references.')}}</p></article><article class="feature"><span>02 / UNDERSTANDING</span><h3>{{t('关系与证据','Relationships and evidence')}}</h3><p>{{t('查看来源、评分上下文、发现轨迹和当前语料的研究版图。','Inspect sources, score contexts, discovery trails and the corpus landscape.')}}</p></article><article class="feature"><span>03 / HANDOFF</span><h3>{{t('判断与交接','Decide and hand off')}}</h3><p>{{t('人工筛选、标定与全文获取各自保留事实，导出可复核的证据包。','Screening, calibration and full-text retrieval preserve distinct facts. Export a reviewable evidence pack.')}}</p></article></div></section>
      <section class="home-band"><div class="row-between"><h2>{{t('最近项目','Recent projects')}}</h2><router-link to="/projects">{{t('查看全部 →','View all →')}}</router-link></div><div v-if="projects.length" class="cols-3"><router-link v-for="p in projects.slice(0,3)" :key="p.project_id" :to="`/projects/${p.project_id}/results`" class="project-card"><h3>{{p.name||p.topic}}</h3><p>{{p.topic}}</p><span>{{p.demo?t('模拟项目','Demo project'):t('研究项目','Research project')}} · {{display(p.updated_at)}}</span></router-link></div><p v-else class="muted">{{t('暂无项目。开始检索或创建隔离演示项目。','No projects yet. Start a search or create an isolated demo.')}}</p></section>
    </template>

    <div v-else-if="!projectError" class="container container-wide">
      <div class="page-head"><div><p v-if="project" class="eyebrow">{{project.name}} <span v-if="project.score_context_id">· {{t('评分批次','Score context')}} {{project.score_context_id}}</span></p><h1>{{title}}</h1><p>{{lead}}</p></div><div class="actions" v-if="projectId"><v-btn variant="outlined" @click="loadPage" :loading="loading">{{t('刷新','Refresh')}}</v-btn></div></div>
      <section v-if="job" class="job-panel" aria-live="polite"><div class="row-between"><strong>{{t('后台任务','Background job')}} · {{label(job.status)}}</strong><v-btn v-if="activeJob" size="small" variant="outlined" :loading="busy" @click="cancelJob">{{t('取消任务','Cancel job')}}</v-btn></div><p>{{job.message||label(job.progress?.stage||job.kind||'')}}</p><div class="job-counts"><span v-for="[key,value] in progressEntries" :key="key">{{key}}: <b>{{display(value)}}</b></span></div><p v-if="job.stop_reason" class="muted">{{t('停止原因','Stop reason')}}: {{label(job.stop_reason)}}</p><p v-if="job.error" class="error-text">{{typeof job.error==='string'?job.error:job.error.message}}</p><ul v-if="job.result?.downloads?.length" class="brief-list mt-4"><li v-for="(result,index) in job.result.downloads" :key="result.paper_key">{{t('文献','Paper')}} {{index+1}} · {{label(result.status)}} <a v-if="result.file?.download_url" :href="result.file.download_url" target="_blank" rel="noopener noreferrer">{{t('打开已获取 PDF ↗','Open retrieved PDF ↗')}}</a><details><summary>{{t('获取依据','Retrieval provenance')}}</summary><pre>{{JSON.stringify(result.provenance,null,2)}}</pre></details></li></ul><v-progress-linear v-if="activeJob" indeterminate color="primary" :height="2" class="mt-3"/></section>

      <v-card v-if="['search','results'].includes(page)&&providerResults.length" class="provider-outcomes form-card mb-6"><div class="row-between"><h3>{{t('上次检索的来源状态','Provider outcomes from the last search')}}</h3><router-link to="/settings">{{t('来源设置 →','Provider settings →')}}</router-link></div><v-alert v-if="hasRateLimit" type="warning" variant="tonal" class="mt-4">{{t('已选择的来源返回了限流。服务已停止该来源的重复请求并进入冷却；请稍后重试、配置凭据，或取消受限来源改查其他库。','A selected provider reported a rate limit. The service stopped repeated requests and entered a cooldown. Retry later, configure credentials, or deselect that source and search other providers.')}}</v-alert><p v-else-if="hasRetrievalFailure" class="error-text mt-4">{{t('部分已选来源未完整结束。已取得的文献仍保留，来源失败不会记为正常零结果。','Some selected providers did not finish. Retrieved records remain available; provider failures are not successful empty results.')}}</p><div class="table-scroll mt-4"><table class="data-table"><thead><tr><th>{{t('来源','Provider')}}</th><th>{{t('状态','Status')}}</th><th>{{t('返回记录','Returned records')}}</th><th>{{t('实际请求','Requests made')}}</th><th>{{t('失败原因','Failure reason')}}</th></tr></thead><tbody><tr v-for="row in providerResults" :key="row.provider"><td>{{sourceLabel(row.provider)}}</td><td>{{label(row.status)}}</td><td>{{row.paper_count}}</td><td>{{row.request_stats?.requests??'—'}}</td><td>{{row.error||'—'}}</td></tr></tbody></table></div><details v-if="providerDiagnostics.length" class="mt-3"><summary>{{t('本次清单保留的来源诊断','Provider diagnostics retained in the run manifest')}}</summary><pre>{{JSON.stringify(providerDiagnostics,null,2)}}</pre></details></v-card>
      <div v-if="page==='search'" class="shell shell-wide main-first">
        <section><v-card class="form-card"><h2>{{t('检索设置','Search settings')}}</h2><form @submit.prevent="search"><v-text-field v-model="query" class="mt-6" :label="t('检索主题或关键词','Search topic or keywords')" maxlength="300" :hint="t('中文研究方向会由本地模型译成英文，再用于检索和排序；请核对译文中的专业术语。','Chinese research directions are translated locally for retrieval and ranking. Check technical terms in the translation.')" persistent-hint :disabled="activeJob" required/><v-textarea v-model="direction" class="mt-4" :label="t('研究方向与关注点','Research direction and focus')" :hint="t('原始研究意图会随项目保存。检索计划会显示实际使用的分库检索式。','The project retains your research intent. The plan shows the queries actually sent to each source.')" persistent-hint rows="3" maxlength="1000"/><v-text-field v-model="englishQuery" class="mt-4" :label="t('英文检索词／译文（可编辑，留空自动翻译）','English query / translation (editable; blank translates automatically)')" :hint="t('首次翻译需下载约 116 MB 模型，之后本地运行；修改研究方向后请清空旧译文。','First translation downloads about 116 MB; subsequent inference is local. Clear the old translation after changing your focus.')" persistent-hint/><v-select v-model="rankingMode" class="mt-4" :label="t('相关度排序','Relevance ranking')" :items="[{title:t('本地语义：标题＋摘要（推荐）','Local semantic: title + abstract'),value:'semantic'},{title:t('关键词排序','Lexical ranking'),value:'lexical'}]"/><v-text-field v-if="!projectId" v-model="name" class="mt-4" :label="t('项目名称（可选）','Project name (optional)')"/><div class="cols-2 mt-6"><v-text-field v-model="yearFrom" type="number" :label="t('起始年份','From year')" min="1990" :max="yearTo"/><v-text-field v-model="yearTo" type="number" :label="t('结束年份','To year')" :min="yearFrom" :max="new Date().getFullYear()"/><v-text-field v-model="maxPapers" type="number" :label="t('文献上限','Record limit')" min="1" max="2000"/><v-select v-model="mode" :items="[{title:t('研究检索','Systematic search'),value:'systematic'},{title:t('主题探索','Scoping search'),value:'scoping'}]" :label="t('检索模式','Search mode')"/></div><fieldset class="provider-pick mt-6"><legend>{{t('检索来源','Search providers')}}</legend><v-checkbox v-for="source in knownProviders" :key="source" v-model="providers" :value="source" :label="sourceLabel(source)" :disabled="activeJob" density="compact" hide-details/><p class="muted">{{t('OpenReview 包含公开未录用投稿；Google Scholar 自动检索需配置 SerpApi API Key，配置后默认启用；接口额度由你的账户决定。短片段不是完整摘要；来源受限时可取消它继续检索。','OpenReview includes public submissions, which may be unaccepted. Google Scholar requires a SerpApi API key and is selected by default once configured; your account determines the quota. Snippets are not full abstracts. Deselect limited providers to continue.')}}</p><router-link to="/settings">{{t('配置来源凭据 →','Configure provider credentials →')}}</router-link></fieldset><div class="actions mt-6"><v-btn type="submit" color="primary" :loading="busy" :disabled="activeJob">{{t('开始检索','Start search')}}</v-btn><v-btn variant="outlined" @click="previewPlan" :disabled="busy||activeJob">{{t('翻译并查看检索计划','Translate and preview query plan')}}</v-btn><v-btn variant="text" @click="loadDemo" :disabled="busy">{{t('离线演示','Offline demo')}}</v-btn></div></form></v-card><v-card v-if="plan" class="form-card mt-6"><h2>{{t('分库检索计划','Provider query plan')}}</h2><p v-if="plan.translation" class="mt-4">{{t('原文','Original')}}：{{plan.translation.original}}<br/>{{t('译文／排序方向','Translation / ranking focus')}}：{{plan.translation.translated}}</p><div class="plan-row" v-for="(value,key) in plannedQueries" :key="key"><strong>{{sourceLabel(key)}}</strong><code>{{typeof value==='object'?JSON.stringify(value,null,2):value}}</code></div><a v-if="plan.queries?.google_scholar?.manual_url" :href="plan.queries.google_scholar.manual_url" target="_blank" rel="noopener noreferrer" class="mt-4 d-block">{{t('在谷歌学术手动检索 ↗','Search manually in Google Scholar ↗')}}</a><details class="mt-4"><summary>{{t('完整计划与降级说明','Full plan and fallback notes')}}</summary><pre>{{JSON.stringify(plan,null,2)}}</pre></details></v-card></section>
        <aside class="side-card" :aria-label="t('研究意图与项目状态','Research intent and project status')"><h3>{{t('研究意图','Research intent')}}</h3><p>{{direction||t('在左侧描述你的研究关注点。','Describe your research focus in the form.')}}</p><hr/><h3>{{t('来源说明','Provider notes')}}</h3><p>{{t('Crossref 用于 DOI 元数据补全。来源限流与超时会保留在任务结果和诊断中。','Crossref supplements DOI metadata. Rate limits and timeouts remain visible in job results and diagnostics.')}}</p><hr/><h3>{{t('项目状态','Project status')}}</h3><p>{{project?label(project.phase):t('开始后创建独立项目','Starting creates an independent project')}}</p><v-text-field v-model="budget" type="number" :label="t('HTTP 请求预算','HTTP request budget')" min="1" max="2000" class="mt-4"/><p class="muted">{{t('具体查询与匹配方式以检索计划及后端记录为准。','The query plan and backend records document the actual query and matching methods.')}}</p></aside>
      </div>

      <div v-else-if="page==='results'" class="shell">
        <aside class="facet-rail" :aria-label="t('结果筛选','Result filters')"><h3>{{t('缩小范围','Refine results')}}</h3><v-select class="mt-4" v-model="filters.provider" :items="sourceOptions" :label="t('来源','Source')" @update:model-value="filterChanged"/><v-select v-model="filters.ccf_rank" @update:model-value="filterChanged" :items="[{title:t('全部级别','All ranks'),value:''},... ['A','B','C'].map(rank=>({title:'CCF-'+rank,value:rank}))]" :label="t('CCF 会议／期刊级别（2026）','CCF venue rank (2026)')"/><v-text-field class="mt-4" v-model="filters.year_from" type="number" :label="t('年份 ≥','Year ≥')" @change="filterChanged"/><v-text-field class="mt-4" v-model="filters.year_to" type="number" :label="t('年份 ≤','Year ≤')" @change="filterChanged"/><label class="field-label mt-4">{{t('最低相关度','Minimum relevance')}} · {{Number(filters.min_score).toFixed(2)}}</label><v-slider v-model="filters.min_score" min="0" max="1" step="0.01" hide-details @end="filterChanged"/><p class="muted">{{t('仅在同一个评分上下文中比较。相关度不代表纳入概率。','Compare within the same score context. Relevance is not an inclusion probability.')}}</p><hr/><h3>{{t('完整语料分面','Corpus facets')}}</h3><div class="facet-row" v-for="row in (facets.providers||[])" :key="row.value"><span>{{sourceLabel(row.value)}}</span><b>{{row.count}}</b></div><p class="muted mt-3">{{t('同一文献可来自多个来源，因此来源数量不可相加作为唯一文献数。','A record can appear in multiple providers. Provider counts do not sum to unique records.')}}</p><v-btn class="mt-4" block variant="outlined" @click="filters={q:'',provider:'',year_from:'',year_to:'',min_score:0,sort:'relevance',page:1,page_size:10};filterChanged()">{{t('清除筛选','Reset filters')}}</v-btn></aside>
        <section class="main-col"><div class="metrics"><article><b>{{display(project?.counts?.records_identified)}}</b><span>{{t('识别记录','Identified records')}}</span></article><article><b>{{display(project?.counts?.records_in_corpus)}}</b><span>{{t('当前唯一文献','Unique corpus records')}}</span></article><article><b>{{total}}</b><span>{{t('筛选后结果','Filtered results')}}</span></article><article><b>{{selected.length}}</b><span>{{t('已选种子','Selected seeds')}}</span></article></div><div class="result-toolbar"><v-text-field v-model="filters.q" :label="t('在标题和摘要中查找','Search titles and abstracts')" clearable @keyup.enter="filterChanged" @click:clear="filterChanged"/><v-select v-model="filters.sort" :items="[{title:t('相关度','Relevance'),value:'relevance'},{title:t('年份：新到旧','Newest first'),value:'year'},{title:t('引用次数','Citations'),value:'citations'}]" :label="t('排序','Sort')" @update:model-value="filterChanged"/><v-select v-model="filters.page_size" :items="[10,20,50]" :label="t('每页','Per page')" @update:model-value="filterChanged"/><v-btn variant="outlined" @click="filterChanged" :loading="busy">{{t('应用','Apply')}}</v-btn></div><div class="selection-bar"><span>{{selected.length}} {{t('篇已选','selected')}}</span><v-btn size="small" variant="text" @click="selectPage">{{t('选择本页','Select page')}}</v-btn><v-btn size="small" variant="text" @click="selected=[];saveSeeds()">{{t('清空','Clear')}}</v-btn><v-btn size="small" color="primary" :disabled="!selected.length" @click="navigate('expand')">{{t('扩展已选种子','Expand selected')}}</v-btn></div><div class="paper-list"><article v-for="paper in papers" :key="paper.paper_key" class="paper-row"><v-checkbox :model-value="selected.includes(paper.paper_key)" @update:model-value="toggleSeed(paper)" hide-details density="compact" :aria-label="`${t('选择','Select')} ${paper.title}`"/><div class="paper-row-content"><button class="paper-title" @click="openPaper(paper)">{{paper.title}}</button><p class="paper-meta">{{paper.year||'—'}} · {{paper.venue||t('来源未标注','Venue unavailable')}} · {{paper.citation_count||0}} {{t('次引用','citations')}}</p><p class="muted"><span v-if="paper.ccf?.rank">{{t('会议／期刊级别','Venue rank')}} CCF-{{paper.ccf.rank}} · </span>{{t('发表状态','Publication status')}}: {{label(paper.publication_status||'unknown')}}<span v-if="!paper.abstract"> · {{t('无摘要：仅标题参与语义排序','No abstract: title-only semantic ranking')}}</span></p><p class="paper-authors">{{authors(paper)}}</p><p v-if="paper.abstract" class="abstract-preview">{{paper.abstract}}</p><div class="paper-badges"><span v-if="paper.screening?.requires_manual_review" class="badge review-needed">{{t('需人工复核','Manual review required')}}</span><span v-for="source in paper.providers||[paper.source]" :key="source" class="badge">{{sourceLabel(source)}}</span><span class="badge">{{t('相关度','Relevance')}} {{percent(paper.relevance_score)}}</span><span v-if="paper.screening" class="badge">{{label(paper.screening.status||paper.screening.title_decision)}}</span></div><div class="paper-links"><a v-if="safeUrl(paper.url)" :href="safeUrl(paper.url)" target="_blank" rel="noopener noreferrer">{{t('论文页面 ↗','Paper page ↗')}}</a><button @click="openPaper(paper)">{{t('发现依据与详情 →','Evidence and details →')}}</button></div></div></article></div><div v-if="!papers.length&&!loading" class="empty"><h3>{{t('没有符合条件的文献','No matching records')}}</h3><p>{{t('调整筛选条件，或返回检索页获取文献。','Adjust the filters or search for literature.')}}</p><p v-if="hasRetrievalFailure" class="error-text mt-4">{{t('本次部分来源没有正常完成，零文献不能视为领域无结果。请查看来源状态。','Some selected sources did not finish normally. Zero records does not establish an absence of literature. Inspect provider outcomes.')}}</p><p v-else-if="providerResults.length" class="muted mt-4">{{t('检索已返回当前结果。可放宽年份、减少限定词，或尝试另一来源。','These are the records returned for this run. Widen the year range, reduce constraints or try another provider.')}}</p><v-btn variant="outlined" @click="navigate('search')">{{t('返回检索','Go to search')}}</v-btn><v-btn class="ml-3" variant="text" to="/settings">{{t('来源设置','Provider settings')}}</v-btn></div><v-pagination v-if="pages>1" v-model="filters.page" :length="pages" :total-visible="5" class="mt-6" @update:model-value="action(loadPapers)"/><div class="next-step"><strong>{{t('下一步','Next step')}}</strong><p>{{t('选择有代表性的种子继续扩展，或在人工筛选页开始判断。','Select representative seeds to expand, or begin human screening.')}}</p><div class="actions"><v-btn variant="outlined" @click="navigate('review')">{{t('人工筛选','Screen papers')}}</v-btn><v-btn variant="outlined" @click="navigate('landscape')">{{t('查看版图','View landscape')}}</v-btn></div></div></section>
      </div>

      <div v-else-if="page==='expand'" class="shell shell-wide main-first"><section><v-card class="form-card"><h2>{{t('选择扩展方式','Choose an expansion method')}}</h2><p>{{selected.length}} {{t('篇种子已选。种子选择保留在当前浏览器项目中。','seeds selected. Selections remain in this browser for the project.')}}</p><v-btn class="mt-3" variant="outlined" @click="navigate('results')">{{t('调整种子','Choose seeds')}}</v-btn><div class="cols-2 mt-6"><v-text-field v-model="rounds" type="number" :label="t('最大轮次','Maximum rounds')" min="1" max="10"/><v-text-field v-model="expansionMax" type="number" :label="t('每方向每轮文献上限','Records per direction per round')" min="1" max="500"/><v-text-field v-model="budget" type="number" :label="t('HTTP 请求预算','HTTP request budget')" min="1" max="2000"/><v-text-field v-model="yearFrom" type="number" :label="t('起始年份','From year')" min="1990"/><v-text-field v-model="yearTo" type="number" :label="t('结束年份','To year')" :max="new Date().getFullYear()"/></div><v-checkbox v-model="resume" :label="t('恢复上次中断的引文扩展','Resume the previous interrupted expansion')" hide-details class="mt-3"/><div class="actions mt-6"><v-btn color="primary" @click="expand" :loading="busy" :disabled="activeJob">{{t('开始双向引文扩展','Expand citations and references')}}</v-btn></div><hr/><h3>{{t('关联文献','Related literature')}}</h3><p>{{t('书目耦合依据共享参考文献，共被引依据共同引用见证；与直接引文分别展示。','Bibliographic coupling uses shared references; co-citation uses common citing witnesses. They remain distinct from citation edges.')}}</p><p class="muted mt-4">{{t('后端组合执行书目耦合与共被引，分别保留关系类型。','The backend runs bibliographic coupling and co-citation together, preserving their distinct relation types.')}}</p><v-btn class="mt-4" variant="outlined" @click="similar" :loading="busy" :disabled="activeJob">{{t('获取关联文献','Find related papers')}}</v-btn></v-card><v-card class="form-card mt-6"><h3>{{t('轮次与运行记录','Rounds and run history')}}</h3><div v-if="project?.run_history?.length" v-for="(run,index) in project.run_history" :key="run.run_id||index" class="run-record"><p><strong>{{run.kind||run.method||t('运行','Run')}}</strong> · {{display(run.created_at||run.timestamp)}} · {{label(run.stop_reason||run.status)}}</p><details><summary>{{t('查看实际记录','Inspect recorded facts')}}</summary><pre>{{JSON.stringify(run,null,2)}}</pre></details></div><p v-else class="muted">{{t('暂无扩展记录。','No expansion runs yet.')}}</p></v-card></section><aside class="side-card" :aria-label="t('扩展状态和预算','Expansion status and budget')"><h3>{{t('停止原因','Stop reason')}}</h3><p>{{label(project?.stop_reason)}}</p><p class="muted">{{t('达到预算、轮次或低新增停止规则，不等于覆盖整个研究领域。','Stopping due to a budget, round limit or low yield does not establish field coverage.')}}</p><hr/><h3>{{t('HTTP 预算','HTTP budget')}}</h3><pre>{{JSON.stringify(project?.http_budget||{},null,2)}}</pre><p>{{t('任务使用后端的实际计数，不显示推算进度百分比。','Jobs display backend counts, not estimated percentages.')}}</p></aside></div>

      <section v-else-if="page==='landscape'">
        <div class="metrics"><article><b>{{graphNodes.length}}</b><span>{{t('图内文献','Graph records')}}</span></article><article><b>{{relationEdges.length}}</b><span>{{t('当前关系','Displayed relationships')}}</span></article><article><b>{{display(landscape?.graph?.edge_type_counts?.citation)}}</b><span>{{t('直接引文边','Citation edges')}}</span></article><article><b>{{display(landscape?.graph?.summary?.communities?.length)}}</b><span>{{t('语料社区','Corpus communities')}}</span></article></div><v-card class="form-card mt-6"><div class="row-between"><h2>{{t('关系网络','Relationship network')}}</h2><v-select v-model="graphMode" class="graph-select" :items="[{title:t('直接引文','Citation'),value:'citation'},{title:t('书目耦合','Bibliographic coupling'),value:'bibliographic_coupling'},{title:t('共被引','Co-citation'),value:'co_citation'},{title:t('全部关系（分色）','All relationships'),value:'all'}]" :label="t('关系类型','Relation type')"/></div><p class="muted">{{t('实线：直接引文；虚线：推导关联。预览最多 48 个节点、160 条边，完整证据保留在导出文件。','Solid: citation. Dashed: derived association. Preview shows at most 48 nodes and 160 edges; exports retain complete evidence.')}}</p><svg v-if="graphNodes.length" class="network" viewBox="0 0 800 460" role="img" :aria-label="t('当前语料关系图','Current corpus relationship network')"><defs><marker id="arrow" viewBox="0 0 10 10" refX="18" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#9ca5af"/></marker></defs><line v-for="(item,i) in visibleGraphEdges" :key="i" :x1="item.a.x" :y1="item.a.y" :x2="item.b.x" :y2="item.b.y" :class="['graph-edge',item.edge.edge_type||item.edge.relation_type||item.edge.type||'citation']" :marker-end="item.edge.edge_type==='citation'?'url(#arrow)':undefined"/><g v-for="node in graphPositions.values()" :key="node.paper_key||node.id" class="graph-node" role="button" tabindex="0" @click="openPaper({paper_key:node.paper_key||node.id})" @keydown.enter="openPaper({paper_key:node.paper_key||node.id})"><circle :cx="node.x" :cy="node.y" r="8"/><title>{{node.title||node.label||node.id}}</title><text :x="node.x" :y="node.y-14" text-anchor="middle">{{(node.title||node.label||node.id||'').slice(0,18)}}</text></g></svg><p v-else class="empty">{{t('暂无已观察到的关系。先检索并进行引文扩展。','No observed relationships yet. Search and expand citations first.')}}</p></v-card><div class="cols-2 mt-6"><v-card class="form-card"><h3>{{t('证据路径','Evidence path')}}</h3><v-select v-model="pathStart" :items="graphNodes.map(p=>({title:p.title||p.label||p.id,value:p.paper_key||p.id}))" class="mt-4" :label="t('起点','Start')"/><v-select v-model="pathEnd" :items="graphNodes.map(p=>({title:p.title||p.label||p.id,value:p.paper_key||p.id}))" class="mt-4" :label="t('终点','End')"/><v-btn class="mt-4" variant="outlined" @click="findPath" :loading="busy">{{t('查找引文路径','Find citation path')}}</v-btn><div v-if="pathResult" class="mt-4"><ol v-if="pathResult.nodes?.length" class="path-list"><li v-for="paper in pathResult.nodes" :key="paper.paper_key"><button @click="openPaper(paper)">{{paper.title}}</button></li></ol><p v-else class="muted">{{t('当前已观察引文中没有这条有向路径。','No directed path was found in the observed citations.')}}</p></div></v-card><v-card class="form-card"><h3>{{t('年度分布','Year distribution')}}</h3><div class="year-bars mt-4"><div v-for="[year,count] in timelineRows" :key="year" class="bar-row"><span>{{year}}</span><div class="bar-track"><div class="bar-fill" :style="{width:(100*count/timelineMax)+'%'}"/></div><b>{{count}}</b></div></div><p v-if="!timelineRows.length" class="muted">{{t('当前语料缺少年份信息。','No year metadata in the current corpus.')}}</p><p class="muted mt-4">{{t('年度分布描述当前样本，增长可能来自检索条件变化。','Year counts describe this sample; growth can reflect retrieval conditions.')}}</p></v-card></div>
        <div class="cols-2 mt-6"><v-card class="form-card"><h3>{{t('主题划分','Corpus topics')}}</h3><article v-for="topic in topicRows" :key="topic.topic_id" class="topic-card"><div class="row-between"><strong>{{topic.topic_id}}</strong><span class="badge">{{topic.size}} {{t('篇','records')}}</span></div><p>{{topic.terms.join(' · ')}}</p><p class="muted">{{t('中位年份','Median year')}} {{display(topic.median_year)}}</p><details><summary>{{t('代表文献','Representative papers')}}</summary><ul class="brief-list"><li v-for="paper in topic.papers" :key="paper.paper_id"><button v-if="paper.paper_key" class="evidence-paper-link" @click="openPaper(paper)">{{paper.title}}</button><span v-else>{{paper.title}}</span> · {{paper.year}}</li></ul></details></article><p v-if="!topicRows.length" class="muted mt-4">{{landscape?.landscape?.topics?.note||t('语料不足，主题划分尚不可用。','Insufficient corpus for topic discovery.')}}</p></v-card><v-card class="form-card"><h3>{{t('主题覆盖','Topic coverage')}}</h3><div v-for="topic in coverage.topics||[]" :key="topic.topic_id" class="coverage-row"><div class="row-between"><span>{{topic.topic_id}} · {{topic.terms.slice(0,3).join(', ')}}</span><b>{{Math.round(100*topic.share)}}%</b></div><div class="bar-track"><div class="bar-fill" :style="{width:(100*topic.share)+'%'}"/></div></div><p class="muted mt-4">{{t('覆盖仅反映当前检索语料在已发现主题间的占比。薄弱主题可能是检索不足。','Coverage is the share of retrieved records among discovered topics. A thin topic can indicate under-retrieval.')}}</p><details><summary>{{t('计算依据','Computation basis')}}</summary><pre>{{JSON.stringify(coverage,null,2)}}</pre></details></v-card></div>
        <v-card class="form-card mt-6"><h3>{{t('相对文本差异','Relative textual distinctiveness')}}</h3><p class="muted mt-3">{{t('与样本中更早文献的词法相似性比较，不能替代原创性或创新性判断。没有更早比较对象时不打分。','Lexical comparison with earlier records in this sample, not a judgment of originality or novelty. Records without earlier comparators are not scored.')}}</p><div class="table-scroll mt-4"><table class="data-table"><thead><tr><th>{{t('文献','Paper')}}</th><th>{{t('年份','Year')}}</th><th>{{t('样本内差异','Distinctiveness')}}</th><th>{{t('最相近的更早文献','Nearest earlier work')}}</th></tr></thead><tbody><tr v-for="row in (novelty.rows||[]).slice(0,20)" :key="row.paper_id"><td>{{row.title}}</td><td>{{row.year}}</td><td>{{row.novelty===null?'—':percent(row.novelty)}}</td><td>{{row.most_similar?.title||t('无更早比较对象','No earlier comparator')}}</td></tr></tbody></table></div><p v-if="!novelty.rows?.length" class="muted">{{novelty.note||t('当前语料不足以计算。','Insufficient corpus to compute.')}}</p></v-card>
      </section>

      <section v-else-if="page==='questions'"><v-alert type="info" variant="tonal">{{t('候选问题是待验证的研究线索；“证据不足”表示当前语料不足，不证明问题没有被研究。','Candidate questions are research leads to validate. Insufficient evidence means the current corpus is incomplete, not that a question is unstudied.')}}</v-alert><div class="cols-2 mt-6"><v-card v-for="(question,index) in questionItems" :key="question.question_id||index" class="form-card"><p class="eyebrow">{{question.category||question.kind||`QUESTION ${index+1}`}}</p><h2>{{question.question||question.title||question.text}}</h2><p>{{question.rationale||question.reason||question.description}}</p><p class="muted">{{t('证据状态','Evidence status')}}: {{display(question.status||question.evidence_status)}} · {{t('证据强度','Evidence strength')}}: {{display(question.evidence_strength)}}</p><div class="actions"><v-btn variant="outlined" @click="questionSelection=question">{{t('查看依据','View evidence')}}</v-btn><v-btn variant="text" @click="router.push({path:currentProjectPath+'/search',query:{q:question.suggested_next_search||question.question||question.title,direction:question.question||question.title}})">{{t('继续检索','Search this question')}}</v-btn></div></v-card></div><p v-if="!questionItems.length&&!loading" class="empty">{{t('当前语料尚未生成候选问题。可先扩大语料，再回来查看。','The corpus has no candidate questions yet. Expand it and return.')}}</p><v-card v-if="questionSelection" class="form-card mt-6"><div class="row-between"><h3>{{t('候选问题的证据记录','Question evidence record')}}</h3><v-btn variant="text" @click="questionSelection=null">{{t('关闭','Close')}}</v-btn></div><h3 class="mt-4">{{t('支持文献','Supporting papers')}}</h3><ul class="brief-list"><li v-for="paper in questionSelection.supporting_papers||[]" :key="paper.paper_id"><button v-if="paper.paper_key" class="evidence-paper-link" @click="openPaper(paper)">{{paper.title}}</button><span v-else>{{paper.title}}</span> · {{paper.year}}</li></ul><p class="mt-4">{{questionSelection.risks}}</p><p class="muted mt-4">{{questionSelection.computation_basis}}</p><details><summary>{{t('完整证据字段','Full evidence fields')}}</summary><pre>{{JSON.stringify(questionSelection,null,2)}}</pre></details></v-card></section>

      <div v-else-if="page==='review'" class="shell shell-wide main-first"><section><div class="review-controls"><v-select v-model="reviewStage" :items="[{title:t('标题与摘要','Title and abstract'),value:'title_abstract'},{title:t('全文筛选','Full text'),value:'full_text'}]" :label="t('人工筛选阶段','Screening stage')"/><v-btn variant="outlined" @click="downloads()" :disabled="!selected.length||activeJob" :loading="busy">{{t('获取已选文献全文','Retrieve selected full texts')}}</v-btn></div><v-text-field v-model="decisionReason" class="mt-4" :label="t('决定理由（排除时填写）','Decision reason (required for exclusion)')"/><v-checkbox v-if="reviewStage==='full_text'" v-model="readConfirmed" :label="t('我已阅读所决定文献的全文','I have read the full text of the paper I am deciding on')" hide-details class="mt-3"/><article v-for="paper in papers" :key="paper.paper_key" class="review-paper"><div class="row-between"><button class="paper-title" @click="openPaper(paper)">{{paper.title}}</button><v-checkbox :model-value="selected.includes(paper.paper_key)" @update:model-value="toggleSeed(paper)" :aria-label="`${t('选择','Select')} ${paper.title}`" hide-details density="compact"/></div><p class="paper-meta">{{paper.year}} · {{label(paper.screening?.title_decision)}} · {{paper.screening?.full_text_retrieved?t('全文已获取','Full text retrieved'):t('全文未获取','Full text not retrieved')}}</p><p>{{paper.abstract||t('摘要不可用，请打开论文页面核实。','Abstract unavailable. Check the paper page.')}}</p><div class="actions"><v-btn color="success" variant="outlined" :disabled="busy||(reviewStage==='full_text'&&(!readConfirmed||paper.screening?.title_decision!=='accept'))" @click="decide(paper,'accept')">{{t('纳入','Include')}}</v-btn><v-btn color="error" variant="outlined" :disabled="busy||!decisionReason.trim()" @click="decide(paper,'reject')">{{t('排除','Exclude')}}</v-btn><v-btn variant="outlined" :disabled="busy" @click="decide(paper,'maybe')">{{t('待定','Maybe')}}</v-btn><v-btn variant="text" @click="downloads([paper.paper_key])" :disabled="busy||activeJob">{{t('获取全文','Retrieve full text')}}</v-btn><a v-if="safeUrl(paper.url)" :href="safeUrl(paper.url)" target="_blank" rel="noopener noreferrer">{{t('打开论文 ↗','Open paper ↗')}}</a></div><div class="calibration-row"><v-select v-model="calibrationLabel" :items="[{title:t('相关','Relevant'),value:'relevant'},{title:t('不相关','Irrelevant'),value:'irrelevant'}]" :label="t('词法排序标定标签','Lexical ranking label')"/><v-btn size="small" variant="outlined" @click="addLabel(paper)">{{t('加入标定','Add label')}}</v-btn></div></article><p v-if="!papers.length" class="empty">{{t('暂无待查看文献。请先执行检索。','No records to review. Run a search first.')}}</p><v-pagination v-if="pages>1" v-model="filters.page" :length="pages" :total-visible="5" @update:model-value="action(loadPapers)"/></section><aside class="side-card" :aria-label="t('筛选事实、标定和获取账本','Screening facts, calibration and retrieval ledger')"><h3>{{t('筛选事实','Screening facts')}}</h3><pre>{{JSON.stringify(review?.facts||review?.screening_facts||review?.prisma||{},null,2)}}</pre><p class="muted">{{t('待决定、未尝试获取、获取失败和人工排除是不同事实。','Pending decisions, retrieval not attempted, failed retrieval and human exclusions are distinct facts.')}}</p><hr/><h3>{{t('相关度标定','Relevance calibration')}}</h3><p>{{calibrationLabels.length}} {{t('个人工标签待提交','human labels ready to submit')}}</p><p class="muted mt-4">{{t('标定阈值由已有后端算法从人工标签中推算；样本不足时保留不可用状态。','The existing backend derives the threshold from human labels; insufficient samples remain marked unusable.')}}</p><v-btn block class="mt-4" variant="outlined" @click="calibrate" :loading="busy">{{t('提交标定','Submit calibration')}}</v-btn><pre class="mt-4">{{JSON.stringify(review?.facts?.calibration||{},null,2)}}</pre><hr/><h3>{{t('全文获取账本','Retrieval ledger')}}</h3><details><summary>{{t('查看逐条状态','Inspect individual statuses')}}</summary><pre>{{JSON.stringify(review?.ledger||[],null,2)}}</pre></details></aside></div>

      <div v-else-if="page==='export'" class="shell shell-wide main-first"><section><v-card class="form-card"><h2>{{t('生成导出文件','Generate export')}}</h2><p>{{t('文献上限和筛选范围以实际项目语料为准。完整证据包包含会话与来源记录。','Exports use the actual project corpus and selected scope. The complete evidence pack contains the session and provenance.')}}</p><div class="cols-2 mt-6"><v-select v-model="exportFormat" @update:model-value="value=>['session','evidence_pack','prisma'].includes(value)&&(exportScope='corpus')" :items="[{title:t('完整证据包 ZIP','Evidence pack ZIP'),value:'evidence_pack'},{title:'CSV',value:'csv'},{title:'RIS',value:'ris'},{title:'BibTeX',value:'bibtex'},{title:t('会话 JSON','Session JSON'),value:'session'},{title:t('PRISMA 事实 JSON','PRISMA facts JSON'),value:'prisma'}]" :label="t('格式','Format')"/><v-select v-model="exportScope" :disabled="['session','evidence_pack','prisma'].includes(exportFormat)" :items="[{title:t('当前全部语料','Entire corpus'),value:'corpus'},{title:t('题目摘要初筛通过','Preliminary included'),value:'preliminary'},{title:t('人工最终纳入','Human included'),value:'included'},{title:t('已选文献','Selected papers'),value:'selected'}]" :label="t('文献范围','Record scope')"/></div><v-btn class="mt-6" color="primary" :loading="busy" @click="exportProject">{{t('生成文件','Generate file')}}</v-btn><div v-if="exportFile" class="download-result mt-6"><strong>{{exportFile.filename||t('导出文件已就绪','Export ready')}}</strong><p>{{display(exportFile.size)}} {{t('字节','bytes')}} · {{exportFile.media_type}}</p><a :href="exportFile.download_url||`/api/exports/${exportFile.export_id}/download`" class="download-link" download>{{t('下载导出文件 ↓','Download export ↓')}}</a></div></v-card><v-card class="form-card mt-6"><h3>{{t('团队接手','Team handoff')}}</h3><p>{{t('把证据包与实际检索主题一起交接。接手者可以导入会话后核查发现轨迹、评分上下文和人工决定。','Share the evidence pack with the actual search topic. Team members can import the session and inspect discovery trails, score contexts and human decisions.')}}</p><p class="muted">{{t('JSON 会话包含项目事实，不包含来源 API 密钥。','Session JSON contains project facts, not provider API keys.')}}</p></v-card></section><aside class="side-card" :aria-label="t('保存与导入会话','Save and import sessions')"><h3>{{t('保存当前项目','Save current project')}}</h3><v-text-field v-model="saveName" class="mt-4" :label="t('项目名称','Project name')"/><p class="muted">{{t('版本','Revision')}} {{display(project?.revision)}}</p><v-btn block class="mt-4" variant="outlined" :loading="busy" @click="save">{{t('保存会话','Save session')}}</v-btn><hr/><h3>{{t('导入会话','Import session')}}</h3><p>{{t('导入经过校验的 JSON，创建独立项目。发生冲突时错误会显示在页面。','Import validated JSON as an independent project. Conflicts are shown on the page.')}}</p><v-btn block class="mt-4" variant="outlined" @click="uploadInput.click()">{{t('选择 JSON 文件','Select JSON file')}}</v-btn><input ref="uploadInput" type="file" accept=".json,application/json" class="visually-hidden" @change="importSession"/><hr/><p v-if="project?.demo" class="muted">{{t('这个项目是模拟数据。导出文件保留演示标记。','This project uses synthetic data. Exports retain the demo marker.')}}</p></aside></div>

      <section v-else-if="page==='projects'"><v-card class="form-card"><h2>{{t('新建研究项目','Create a research project')}}</h2><div class="cols-2 mt-4"><v-text-field v-model="name" :label="t('项目名称','Project name')"/><v-text-field v-model="query" :label="t('研究主题','Research topic')"/></div><div class="actions mt-4"><v-btn color="primary" @click="createProject" :loading="busy">{{t('创建项目','Create project')}}</v-btn><v-btn variant="outlined" @click="loadDemo" :disabled="busy">{{t('创建隔离演示','Create isolated demo')}}</v-btn><v-btn variant="text" @click="uploadInput.click()">{{t('导入会话','Import session')}}</v-btn><input ref="uploadInput" type="file" accept=".json,application/json" class="visually-hidden" @change="importSession"/></div></v-card><div class="cols-3 mt-6"><router-link v-for="p in projects" :key="p.project_id" :to="`/projects/${p.project_id}/results`" class="project-card"><div class="row-between"><span class="badge">{{p.demo?t('模拟项目','Synthetic demo'):t('研究项目','Research project')}}</span><span>{{display(p.counts?.records_in_corpus??p.paper_count)}} {{t('篇','records')}}</span></div><h3>{{p.name||p.topic||p.project_id}}</h3><p>{{p.topic}}</p><span>{{t('更新于','Updated')}} {{display(p.updated_at)}}</span></router-link></div><p v-if="!projects.length&&!loading" class="empty">{{t('暂无项目，创建一个项目开始。','No projects yet. Create one to start.')}}</p></section>

      <section v-else-if="page==='settings'"><div class="cols-2"><v-card class="form-card"><h2>{{t('来源配置','Provider configuration')}}</h2><div v-for="source in ['s2','openalex','google_scholar','unpaywall']" :key="source" class="config-state"><strong>{{sourceLabel(source)}}</strong><span :class="['badge',(settings?.providers?.[source==='s2'?'semantic_scholar':source]?.configured)?'configured':'']">{{(settings?.providers?.[source==='s2'?'semantic_scholar':source]?.configured)?t('已配置','Configured'):t('未配置','Not configured')}}</span></div><form @submit.prevent="saveCredentials"><v-text-field v-model="keyInputs.s2_api_key" type="password" autocomplete="new-password" class="mt-6" label="Semantic Scholar API Key"/><v-text-field v-model="keyInputs.openalex_api_key" type="password" autocomplete="new-password" class="mt-4" label="OpenAlex API Key"/><v-text-field v-model="keyInputs.serpapi_api_key" type="password" autocomplete="new-password" class="mt-4" label="Google Scholar / SerpApi API Key"/><v-text-field v-model="keyInputs.unpaywall_email" type="password" autocomplete="new-password" class="mt-4" :label="t('Unpaywall 邮箱','Unpaywall email')"/><p class="muted mt-4">{{t('留空表示保持已有配置。提交后立即清空输入；服务端不会返回密钥内容。','Empty fields retain existing configuration. Inputs are cleared after submission; the server never returns credentials.')}}</p><v-btn type="submit" color="primary" :loading="busy" class="mt-4">{{t('保存配置','Save configuration')}}</v-btn><p v-if="credentialsMessage" class="mt-4" role="status">{{credentialsMessage}}</p></form></v-card><v-card class="form-card"><h2>{{t('界面偏好','Interface preferences')}}</h2><v-select v-model="lang" class="mt-6" :items="[{title:'简体中文',value:'zh'},{title:'English',value:'en'}]" :label="t('界面语言','Interface language')"/><v-switch v-model="reduced" :label="t('减少动态效果','Reduce motion')" hide-details class="mt-4"/><p class="muted mt-4">{{t('语言与动态效果保存在当前浏览器。页面也会遵守系统的减少动态效果设置。','Language and motion preferences remain in this browser. The interface also respects the system reduced-motion setting.')}}</p><hr/><h3>{{t('本机服务','Local server')}}</h3><p>{{t('来源请求、项目保存和导出由本机后端执行。','The local backend handles provider requests, project persistence and exports.')}}</p><v-btn class="mt-4" variant="outlined" @click="loadPage" :loading="loading">{{t('刷新诊断','Refresh diagnostics')}}</v-btn></v-card></div><v-card class="form-card mt-6"><h2>{{t('服务诊断','Service diagnostics')}}</h2><pre class="mt-4">{{JSON.stringify(health||{},null,2)}}</pre></v-card></section>
    </div>

    <section v-if="page==='paper'&&detail" class="paper-background container"><v-btn variant="outlined" @click="backToResults">{{t('← 返回结果','← Back to results')}}</v-btn><p class="mt-6">{{t('论文详情已在右侧打开；关闭后回到当前项目结果。','Paper details are open in the panel. Close it to return to the project results.')}}</p></section>
  </main>
  <v-navigation-drawer v-if="page==='paper'&&detail" :model-value="true" location="right" temporary class="paper-drawer" :width="drawerWidth" @update:model-value="value=>!value&&backToResults()"><div class="drawer-inner"><div class="row-between"><span class="eyebrow">{{t('论文详情','Paper details')}}</span><v-btn variant="text" @click="backToResults" :aria-label="t('关闭论文详情','Close paper details')">{{t('关闭','Close')}} ×</v-btn></div><h1>{{detail.title}}</h1><p class="paper-meta mt-3">{{detail.year}} · {{detail.venue}} · {{detail.citation_count||0}} {{t('次引用','citations')}}</p><p v-if="detail.ccf?.rank" class="mt-3">CCF-{{detail.ccf.rank}} ({{detail.ccf.edition}}) · {{detail.ccf.note}}</p><p class="mt-3">{{authors(detail)}}</p><div class="actions mt-4"><v-btn variant="outlined" @click="toggleSeed(detail)">{{selected.includes(detail.paper_key)?t('取消种子选择','Deselect seed'):t('设为扩展种子','Select as seed')}}</v-btn><v-btn v-if="safeUrl(detail.url)" :href="safeUrl(detail.url)" target="_blank" rel="noopener noreferrer" color="primary">{{t('打开论文页面 ↗','Open paper page ↗')}}</v-btn></div><hr/><h3>{{t('摘要','Abstract')}}</h3><p class="full-abstract">{{detail.abstract||t('摘要不可用，请从论文页面核查。','Abstract unavailable. Check the paper page.')}}</p><hr/><h3>{{t('相关度与评分上下文','Relevance and score context')}}</h3><p>{{t('相关度','Relevance')}} {{percent(detail.relevance_score)}} · {{detail.score_context_id||'—'}}</p><p class="muted">{{t('相关度是当前查询的排序依据，不是纳入概率或论文质量。','Relevance ranks the current query; it is not inclusion probability or paper quality.')}}</p><p v-if="detail.score_breakdown?.semantic!==undefined" class="muted">{{t('本地多语言 MiniLM：标题与完整摘要分块编码，语义 60%＋关键词 15%＋方向概念覆盖 25%。','Local multilingual MiniLM: title and complete abstract chunks; semantic 60% + lexical 15% + focus coverage 25%.')}}</p><pre>{{JSON.stringify(detail.score_breakdown||{},null,2)}}</pre><hr/><div v-if="detail.search_snippet" class="mt-6"><h3>{{t('检索片段（非完整摘要）','Search snippet (not a full abstract)')}}</h3><p>{{detail.search_snippet}}</p></div><h3>{{t('发现轨迹','Discovery trail')}}</h3><article v-for="(trace,index) in detail.discovery_traces||[]" :key="index" class="trace"><strong>{{trace.method}} · {{sourceLabel(trace.provider)}}</strong><p v-if="trace.query">{{t('查询','Query')}}: {{trace.query}}</p><p v-if="trace.seed_id">{{t('种子','Seed')}}: {{trace.seed_id}}</p><details><summary>{{t('查看证据字段','Inspect evidence fields')}}</summary><pre>{{JSON.stringify(trace,null,2)}}</pre></details></article><p v-if="!detail.discovery_traces?.length" class="muted">{{t('没有保存的发现轨迹。旧会话可能缺少这些字段。','No saved discovery trails. Older sessions may lack these fields.')}}</p><hr/><h3>{{t('筛选与获取状态','Screening and retrieval status')}}</h3><pre>{{JSON.stringify(detail.screening||{},null,2)}}</pre><h3 class="mt-6">{{t('关系依据','Relationship evidence')}}</h3><pre>{{JSON.stringify(detail.relations||[],null,2)}}</pre><p class="muted">{{detail.canonical_id}}</p></div></v-navigation-drawer>
  <footer class="footer"><router-link to="/">LEExtractor</router-link><span>{{t('惟学无际，际于天地','Knowledge without limits')}}</span><span>{{t('证据留下，判断由你。','Keep the evidence. Make the judgment.')}}</span></footer>
</v-app>
</template>
